From 61da4d51792535616a1267ecf87cc9a73d44279b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:18:35 +0100
Subject: [PATCH] applets/notes: allow choosing a custom font family

Sticky Notes only let you change the font size, so notes always used the
system font even when someone wanted a handwriting-style typeface. Add a
font chooser next to the size, applied to existing text like the size.

BUG: 477726
---
 applets/notes/main.xml                 |  4 +++
 applets/notes/qml/configAppearance.qml | 44 ++++++++++++++++++++++++++
 applets/notes/qml/main.qml             | 11 +++++++
 3 files changed, 59 insertions(+)

diff --git a/applets/notes/main.xml b/applets/notes/main.xml
index 552e3c2fd..407904884 100644
--- a/applets/notes/main.xml
+++ b/applets/notes/main.xml
@@ -14,6 +14,10 @@
     <entry name="fontSize" type="int">
     </entry>

+    <entry name="fontFamily" type="String">
+      <default></default>
+    </entry>
+
     <entry name="noteId" type="String">
       <default></default>
     </entry>
diff --git a/applets/notes/qml/configAppearance.qml b/applets/notes/qml/configAppearance.qml
index 724afb1ab..043c4615d 100644
--- a/applets/notes/qml/configAppearance.qml
+++ b/applets/notes/qml/configAppearance.qml
@@ -6,6 +6,7 @@

 import QtQuick
 import QtQuick.Controls as QQC2
+import Qt.labs.platform as Platform

 import org.kde.kcmutils as KCM
 import org.kde.plasma.core as PlasmaCore
@@ -17,6 +18,7 @@ KCM.GridViewKCM {
     id: kcm
     property string cfg_color
     property alias cfg_fontSize: fontSizeSpinBox.value
+    property string cfg_fontFamily

     readonly property bool inPanel: [PlasmaCore.Types.TopEdge, PlasmaCore.Types.RightEdge,PlasmaCore.Types.BottomEdge, PlasmaCore.Types.LeftEdge].includes(Plasmoid.location)

@@ -39,6 +41,48 @@ KCM.GridViewKCM {
                     }
                 }
             }
+
+            Kirigami.FormEntry {
+                title: i18nc("@label:chooser", "Text font:")
+                contentItem: QQC2.Button {
+                    text: kcm.cfg_fontFamily || i18nc("@action:button the system's default font is used", "Default")
+                    icon.name: "preferences-desktop-font"
+                    onClicked: {
+                        fontDialog.open();
+                        fontDialog.currentFont = Qt.font({
+                            family: kcm.cfg_fontFamily || Kirigami.Theme.defaultFont.family,
+                            pointSize: kcm.cfg_fontSize,
+                        });
+                    }
+                }
+                trailingItems: [
+                    QQC2.Button {
+                        visible: kcm.cfg_fontFamily !== ""
+                        text: i18nc("@action:button", "Use Default Font")
+                        display: QQC2.AbstractButton.IconOnly
+                        icon.name: "edit-reset"
+                        onClicked: kcm.cfg_fontFamily = ""
+
+                        QQC2.ToolTip.text: text
+                        QQC2.ToolTip.visible: hovered
+                        QQC2.ToolTip.delay: Kirigami.Units.toolTipDelay
+                    }
+                ]
+            }
+        }
+    }
+
+    Platform.FontDialog {
+        id: fontDialog
+        title: i18nc("@title:window", "Choose a Font")
+        modality: Qt.WindowModal
+        parentWindow: kcm.Window.window
+
+        onAccepted: {
+            kcm.cfg_fontFamily = font.family;
+            if (font.pointSize > 0) {
+                kcm.cfg_fontSize = Math.round(font.pointSize);
+            }
         }
     }

diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index f07705ade..1941189d1 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -188,6 +188,7 @@ PlasmoidItem {
                 PlasmaComponents3.TextArea {
                     id: mainTextArea
                     property int cfgFontPointSize: Plasmoid.configuration.fontSize
+                    readonly property string cfgFontFamily: Plasmoid.configuration.fontFamily || Kirigami.Theme.defaultFont.family

                     textFormat: TextEdit.RichText
                     onLinkActivated: link => Qt.openUrlExternally(link)
@@ -197,6 +198,7 @@ PlasmoidItem {
                     wrapMode: TextEdit.Wrap

                     font.pointSize: cfgFontPointSize
+                    font.family: cfgFontFamily

                     // Hide the blinking cursor while text is selected, like most rich text editors
                     onSelectedTextChanged: cursorVisible = activeFocus && selectedText.length === 0
@@ -250,6 +252,15 @@ PlasmoidItem {
                         select(start, end);
                     }

+                    onCfgFontFamilyChanged: {
+                        const start = selectionStart;
+                        const end = selectionEnd;
+
+                        selectAll();
+                        documentHandler.fontFamily = cfgFontFamily;
+                        select(start, end);
+                    }
+
                     // Save semi-continuously to prevent possible data loss
                     onTextChanged: {
                         throttledTextSaver?.restart();
-- 
2.53.0
